                && (active_tail.is_empty()
                    || active_tail.eq_ignore_ascii_case("bearer")
                    || active_tail.eq_ignore_ascii_case("basic")
                    || active_tail.eq_ignore_ascii_case("token")
                    || active_tail.eq_ignore_ascii_case("digest"));
